import { useState } from "react"
import { toast } from "react-hot-toast"
import { AiOutlineEye, AiOutlineEyeInvisible } from "react-icons/ai"
import { useDispatch } from "react-redux"
import { useNavigate } from "react-router-dom"

import { sendOtp } from "../../../services/operations/authAPI"
import { setSignupData } from "../../../slices/authSlice"
import { ACCOUNT_TYPE } from "../../../utils/constants"
import Tab from "../../common/Tab"


function SignupForm() {
  const [accountType, setAccountType] = useState("student");
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    password: "",
    confirmPassword: "",
  });

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const { firstName, lastName, email, password, confirmPassword } = formData;

  const handleOnChange = (e) => {
    setFormData((prevData) => ({
      ...prevData,
      [e.target.name]: e.target.value,
    }));
  };

  const handleOnSubmit = (e) => {
    e.preventDefault();

    if (password !== confirmPassword) {
      alert("Passwords Do Not Match");
      return;
    }

    const signupData = {
      ...formData,
      accountType,
    };

    console.log("Form submitted:", signupData);

    // Reset form
    setFormData({
      firstName: "",
      lastName: "",
      email: "",
      password: "",
      confirmPassword: "",
    });
    setAccountType("student");
  };

  const tabData = [
    {
      id: 1,
      tabName: "Student",
      type: "student",
    },
    {
      id: 2,
      tabName: "Instructor",
      type: "instructor",
    },
  ];

  return (
    <div className="min-h-screen bg-gray-900 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-gray-800 rounded-lg shadow-xl p-6">
        <h2 className="text-2xl font-bold text-white mb-6 text-center">Create Account</h2>

        {/* Account Type Selector */}
        <div className="flex gap-4 mb-6">
          {tabData.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setAccountType(tab.type)}
              className={`flex-1 py-2 px-4 rounded-md capitalize ${
                accountType === tab.type
                  ? "bg-blue-600 text-white"
                  : "bg-gray-700 text-gray-300"
              }`}
            >
              {tab.tabName}
            </button>
          ))}
        </div>

        <form onSubmit={handleOnSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="firstName" className="block text-gray-300 mb-1">
                First Name <sup className="text-pink-500">*</sup>
              </label>
              <input
                id="firstName"
                required
                type="text"
                name="firstName"
                value={firstName}
                onChange={handleOnChange}
                placeholder="Enter first name"
                autoComplete="given-name"
                className="w-full bg-gray-700 text-white rounded-md p-2 border border-gray-600 focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
            </div>
            <div>
              <label htmlFor="lastName" className="block text-gray-300 mb-1">
                Last Name <sup className="text-pink-500">*</sup>
              </label>
              <input
                id="lastName"
                required
                type="text"
                name="lastName"
                value={lastName}
                onChange={handleOnChange}
                placeholder="Enter last name"
                autoComplete="family-name"
                className="w-full bg-gray-700 text-white rounded-md p-2 border border-gray-600 focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
            </div>
          </div>

          <div>
            <label htmlFor="email" className="block text-gray-300 mb-1">
              Email Address <sup className="text-pink-500">*</sup>
            </label>
            <input
              id="email"
              required
              type="email"
              name="email"
              value={email}
              onChange={handleOnChange}
              placeholder="Enter email address"
              autoComplete="email"
              className="w-full bg-gray-700 text-white rounded-md p-2 border border-gray-600 focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="relative">
              <label htmlFor="password" className="block text-gray-300 mb-1">
                Create Password <sup className="text-pink-500">*</sup>
              </label>
              <input
                id="password"
                required
                type={showPassword ? "text" : "password"}
                name="password"
                value={password}
                onChange={handleOnChange}
                placeholder="Enter Password"
                autoComplete="new-password"
                className="w-full bg-gray-700 text-white rounded-md p-2 pr-10 border border-gray-600 focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
              <button
                type="button"
                onClick={() => setShowPassword((prev) => !prev)}
                className="absolute right-2 top-[38px] text-gray-400 hover:text-gray-300"
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
              </button>
            </div>

            <div className="relative">
              <label htmlFor="confirmPassword" className="block text-gray-300 mb-1">
                Confirm Password <sup className="text-pink-500">*</sup>
              </label>
              <input
                id="confirmPassword"
                required
                type={showConfirmPassword ? "text" : "password"}
                name="confirmPassword"
                value={confirmPassword}
                onChange={handleOnChange}
                placeholder="Confirm Password"
                autoComplete="new-password"
                className="w-full bg-gray-700 text-white rounded-md p-2 pr-10 border border-gray-600 focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword((prev) => !prev)}
                className="absolute right-2 top-[38px] text-gray-400 hover:text-gray-300"
                aria-label={showConfirmPassword ? "Hide password" : "Show password"}
              >
                {showConfirmPassword ? <EyeOff size={20} /> : <Eye size={20} />}
              </button>
            </div>
          </div>

          <button
            type="submit"
            className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition-colors mt-6 font-medium"
          >
            Create Account
          </button>
        </form>
      </div>
    </div>
  );
}

export default SignupForm;
